      var rb0 = RB ? (RB[x.name] != null ? RB[x.name] : x.trend ? 0 : x.pct) : 0, PK = K && K.park && K.park.on;   // 🧭 10/28: 추세 주차 칸은 💼 에만(킥 기본 칸은 규칙 비중 그대로)
