    var d1 = PB && PB.score && PB.score.all && PB.score.all.d1 || {}, okN = d1.n ? Math.round(d1.hit / 100 * d1.n) : 0, proven = (d1.n || 0) >= 20 && (d1.hit || 0) >= 55;
