  /* ---------- A9-4 🪄 숫자 차오름 + 지난번 본 값 ---------- */
  var SEEN = {}; try { SEEN = JSON.parse(localStorage.getItem("ch_seen") || "{}") || {}; } catch(x) {}
  var animated = {};
